from pybricks.hubs import PrimeHub
from pybricks.parameters import Direction, Port, Stop
from pybricks.pupdevices import Motor
from pybricks.robotics import DriveBase

# Set up all devices.
prime_hub = PrimeHub()
leftmotor = Motor(Port.B, Direction.CLOCKWISE)
rightmotor = Motor(Port.A, Direction.COUNTERCLOCKWISE)
drive_base = DriveBase(leftmotor, rightmotor, 56, 114)
motor_3 = Motor(Port.D, Direction.COUNTERCLOCKWISE)


# The main program starts here.
print('Hello, Pybricks!')
drive_base.settings(straight_speed=200)
drive_base.settings(turn_rate=75)
drive_base.straight(240)
drive_base.turn(90)
drive_base.straight(420)
motor_3.run_angle(200, 90)
drive_base.straight(-386)
# Will drive to the mission and lift he red thing up.
